import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { activityFilterSchema } from "@/schemas/activity";
import { getDb } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import { runWebhookDeliveryJob } from "@/server/jobs/webhook-delivery-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { NotFoundError } from "@/server/services/_support";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import { notify } from "@/server/services/notification-service";
import {
  createOrganization,
  deleteOrganization,
  restoreOrganization,
} from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
const detachers: Unsubscribe[] = [];
const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

function countRows(table: string, orgId: string): number {
  const column = table === "organizations" ? "id" : "org_id";
  const row = getDb()
    .$client.prepare(`SELECT count(*) AS n FROM "${table}" WHERE ${column} = ?`)
    .get(orgId) as { n: number };
  return row.n;
}

const TABLES = [
  "organizations",
  "organization_usage",
  "members",
  "invitations",
  "projects",
  "issues",
  "activity_events",
  "subscriptions",
  "webhook_endpoints",
  "webhook_deliveries",
];

async function populate(tenant: Tenant) {
  await usageRepo.recomputeUsage(tenant.org.id);
  const issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, {
      title: "Late",
      assigneeId: tenant.userIds.member,
      dueAt: "2026-01-01T00:00:00.000Z",
    }),
  );
  const endpoint = await webhookRepo.insertEndpoint(
    { orgId: tenant.org.id, url: "https://example.com/hook", eventTypes: ["issue.created"] },
    "secret",
  );
  const delivery = await webhookRepo.enqueueDelivery(
    tenant.org.id,
    endpoint.id,
    "issue.created",
    "{}",
  );
  const token = `tok-${tenant.org.slug}`.padEnd(32, "x");
  const invitation = await invitationRepo.insertInvitation(
    tenant.org.id,
    { orgId: tenant.org.id, email: `new@${tenant.org.slug}.test`, role: "member", expiresInDays: 14 },
    tenant.userIds.admin,
    hashToken(token),
  );
  return { issue, delivery, token, invitation };
}

describe("workspace deletion lifecycle", () => {
  it("keeps a deleted workspace inert, then restores it", async () => {
    const tenant = await createTenant("lifecycle");
    const { delivery, token, invitation } = await populate(tenant);

    const deletedEvents: unknown[] = [];
    const restoredEvents: unknown[] = [];
    detachers.push(subscribe("organization.deleted", (p) => void deletedEvents.push(p)));
    detachers.push(subscribe("organization.restored", (p) => void restoredEvents.push(p)));

    const deleted = await deleteOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      confirmSlug: tenant.org.slug,
    });
    expect(deleted.archivedAt).not.toBeNull();
    expect(deletedEvents).toEqual([
      expect.objectContaining({ orgId: tenant.org.id, actorId: tenant.userIds.owner, slug: "lifecycle" }),
    ]);

    await expect(
      deleteOrganization(tenant.actors.owner, { orgId: tenant.org.id, confirmSlug: tenant.org.slug }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const audit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.deleted"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      subjectKind: "organization",
      subjectId: tenant.org.id,
      actorId: tenant.userIds.owner,
    });
    expect(
      activityFilterSchema.safeParse({ orgId: tenant.org.id, action: ["organization.deleted", "organization.restored"] }).success,
    ).toBe(true);

    // sign-in & listing
    await expect(
      resolveActorForOrg({ userId: tenant.userIds.owner, email: "x", activeOrgId: null, expiresAt: "2099-01-01T00:00:00.000Z" as never }, "lifecycle"),
    ).resolves.toBeNull();
    expect((await orgRepo.listOrgsForUser(tenant.userIds.owner)).map((o) => o.id)).not.toContain(tenant.org.id);

    // slug stays reserved
    const other = await createOrganization(tenant.userIds.owner, { name: "Other", slug: "lifecycle", plan: "free" });
    expect(other.slug).not.toBe("lifecycle");

    // notifications
    await expect(
      notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin], { title: "t", body: "b", href: "/", actorId: null }),
    ).resolves.toEqual([]);

    // invitations
    const newUser = await userRepo.insertUser({ email: "new@lifecycle.test", name: "New", passwordHash: "seed" });
    await expect(invitationService.acceptInvitation(newUser.id, { token })).rejects.toBeInstanceOf(NotFoundError);
    expect((await invitationRepo.listPendingInvitations(tenant.org.id)).map((i) => i.id)).toContain(invitation.id);

    // jobs
    const overdue: string[] = [];
    detachers.push(subscribe("issue.overdue", (p) => void overdue.push(p.orgId)));
    await runOverdueIssueJob(new Date());
    expect(overdue).not.toContain(tenant.org.id);

    const usageBefore = await usageRepo.getUsage(tenant.org.id);
    await runUsageRollupJob(new Date());
    expect((await usageRepo.getUsage(tenant.org.id)).measuredAt).toBe(usageBefore.measuredAt);

    await runTrialExpiryJob(new Date(Date.now() + 20 * DAY));
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.plan).toBe("growth");

    await runWebhookDeliveryJob(new Date());
    const deliveryRow = getDb().$client
      .prepare("SELECT status FROM webhook_deliveries WHERE id = ?")
      .get(delivery.id) as { status: string };
    expect(deliveryRow.status).toBe("failed");

    const before = TABLES.map((t) => countRows(t, tenant.org.id));
    await runCleanupArchivedJob(new Date(Date.now() + 29 * DAY));
    expect(TABLES.map((t) => countRows(t, tenant.org.id))).toEqual(before);

    // restore
    const stranger = await userRepo.insertUser({ email: "s@lifecycle.test", name: "S", passwordHash: "seed" });
    await expect(restoreOrganization(stranger.id, tenant.org.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(restoreOrganization(tenant.userIds.admin, tenant.org.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    const restored = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(restored.archivedAt).toBeNull();
    expect(restoredEvents).toHaveLength(1);
    expect(restoredEvents[0]).toMatchObject({ actorId: tenant.userIds.owner, slug: "lifecycle" });

    const again = await restoreOrganization(tenant.userIds.owner, tenant.org.id);
    expect(again.archivedAt).toBeNull();
    expect(restoredEvents).toHaveLength(1);

    const restoredAudit = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["organization.restored"],
      limit: 25,
      cursor: null,
    });
    expect(restoredAudit.items).toHaveLength(1);

    await expect(resolveActorForOrg({ userId: tenant.userIds.owner, email: "x", activeOrgId: null, expiresAt: "2099-01-01T00:00:00.000Z" as never }, "lifecycle")).resolves.not.toBeNull();
    const member = await invitationService.acceptInvitation(newUser.id, { token });
    expect(member.orgId).toBe(tenant.org.id);

    await expect(restoreOrganization(tenant.userIds.owner, "01HZZZZZZZZZZZZZZZZZZZZZZZ" as never)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a restore once the window has closed and purges on the sweep", async () => {
    const tenant = await createTenant("purgeme");
    await populate(tenant);
    const session = await sessionRepo.createSession(tenant.userIds.owner, "hash-purge", "2099-01-01T00:00:00.000Z" as never);
    getDb().$client.prepare("UPDATE sessions SET active_org_id = ? WHERE token_hash = ?").run(tenant.org.id, "hash-purge");
    void session;

    const deletedAt = Date.now();
    await deleteOrganization(tenant.actors.owner, { orgId: tenant.org.id, confirmSlug: "purgeme" });

    vi.useFakeTimers();
    vi.setSystemTime(new Date(deletedAt + 30 * DAY + 1000));
    await expect(restoreOrganization(tenant.userIds.owner, tenant.org.id)).rejects.toBeInstanceOf(NotFoundError);
    vi.useRealTimers();

    const live = await createTenant("purgelive");
    await populate(live);
    const liveBefore = TABLES.map((t) => countRows(t, live.org.id));

    const result = await runCleanupArchivedJob(new Date(deletedAt + 30 * DAY + 1000));
    expect(result.failed).toBe(0);
    expect(TABLES.map((t) => countRows(t, tenant.org.id))).toEqual(TABLES.map(() => 0));
    expect(TABLES.map((t) => countRows(t, live.org.id))).toEqual(liveBefore);
    expect(await userRepo.findUserById(tenant.userIds.owner)).not.toBeNull();
    expect(await sessionRepo.findSessionByTokenHash("hash-purge")).toMatchObject({ activeOrgId: null });
    expect(await usageRepo.listOrgIdsForRollup(1000)).not.toContain(tenant.org.id);

    await expect(restoreOrganization(tenant.userIds.owner, tenant.org.id)).rejects.toBeInstanceOf(NotFoundError);
    const reborn = await createOrganization(tenant.userIds.owner, { name: "Again", slug: "purgeme", plan: "free" });
    expect(reborn.slug).toBe("purgeme");
  });
});

